import{_ as h,c as d,o as c,a2 as p}from"./chunks/framework.jqDK1qTK.js";const u="/assets/scene-0.DKfkBKHM.png",m="/assets/podrick_no_logo.C0dpj8Te.png",t="/assets/icon_plot.CFNmc_FW.png",g="/assets/scene-1.C-NvEBWu.png",a="/assets/icon_raccoon.CpXVYoTt.png",f="/assets/scene-2.BeLvmRyu.png",b="/assets/scene-3.obVk91ML.png",r="/assets/icon_library_outside.BBowQiCi.png",y="/assets/scene-4.DOgj8Yvl.png",i="/assets/icon_scrolls.BvZDLBLm.png",k="/assets/scene-5.BgsJE8nT.png",n="/assets/icon_gilly_no_background.0gUNp_TJ.png",w="/assets/scene-6.BzQ7_Vlk.png",o="/assets/icon_nursery.DwFYPLZX.png",q="/assets/scene-7.aDCOHtJW.png",s="/assets/icon_beaver_infra.BXZuhorS.png",v="/assets/scene-8.BIYAEtj6.png",l="/assets/icon_beaver_mcm.B14lm-Ua.png",_="/assets/scene-9.CoiHZyDA.png",x="/assets/icon_gilly_scaling.CBh6x_qg.png",P="/assets/scene-10.BqjWubQK.png",E="/assets/scene-11.BQktay9n.png",I="/assets/icon_day2_operations.Bot_rGuh.png",T="/assets/scene-12.DUgqnKbn.png",z=JSON.parse('{"title":"Podrick and the Infinite Garden","description":"","frontmatter":{"github_repo":"https://github.com/gardener/documentation","github_subdir":"website/documentation/getting-started","params":{"github_branch":"master"},"path_base_for_github_subdir":{"from":"content/docs/getting-started/podrick-and-the-infinite-garden.md","to":"podrick-and-the-infinite-garden.md"},"title":"Podrick and the Infinite Garden","weight":0,"prev":false,"next":false},"headers":[],"relativePath":"docs/getting-started/podrick-and-the-infinite-garden/index.md","filePath":"docs/getting-started/podrick-and-the-infinite-garden.md","lastUpdated":null}'),G={name:"docs/getting-started/podrick-and-the-infinite-garden/index.md"};function B(S,e,C,K,A,W){return c(),d("div",null,e[0]||(e[0]=[p('<h1 id="podrick-and-the-infinite-garden" tabindex="-1">Podrick and the Infinite Garden <a class="header-anchor" href="#podrick-and-the-infinite-garden" aria-label="Permalink to &quot;Podrick and the Infinite Garden&quot;">​</a></h1><p><strong>An Illustrated Guide to Gardener for Readers of All Ages</strong></p><p><img src="'+u+'" alt="cover picture of podrick and the infinite garden"></p><ul><li><strong>Written by:</strong> <em>The Gardener authors</em></li><li><strong>Inspiration:</strong> <a href="https://www.cncf.io/phippy/the-childrens-illustrated-guide-to-kubernetes/" target="_blank" rel="noreferrer"><em>The Illustrated Children&#39;s Guide to Kubernetes</em></a></li><li><strong>Illustrations:</strong> <em>generated with <a href="https://gemini.google/overview/image-generation/" target="_blank" rel="noreferrer">Gemini Nano Banana Pro</a></em></li></ul><h2 id="meet-podrick" tabindex="-1">Meet Podrick <a class="header-anchor" href="#meet-podrick" aria-label="Permalink to &quot;Meet Podrick&quot;">​</a></h2><p>Podrick was a simple earthworm with a complex dream. While most worms were content tunneling through a single patch of dirt, Podrick had ambition. He had collected thousands of rare and delicate plants. Among them were orchids that needed humidity, cacti that craved dry heat, and ferns that demanded shade.</p><p>To keep them alive, he needed plots (<em>Kubernetes clusters</em>). Many plots in different environments but all with a similar set of features to ease maintenance efforts.</p><p><img src="'+m+'" alt="podrick is an earthworm and main protagonist of the story"></p><h2 id="explanation-kubernetes-clusters" tabindex="-1"><em>Explanation: Kubernetes Clusters</em> <a class="header-anchor" href="#explanation-kubernetes-clusters" aria-label="Permalink to &quot;*Explanation: Kubernetes Clusters*&quot;">​</a></h2><ul><li>Host containerized workloads.</li><li>Can be configured in many ways.</li><li>Need to be scaled, updated and maintained regularly.</li></ul><img src="'+t+'" style="width:50%;" alt="a farm plot growing different vegetables representing a kubernetes cluster"><hr><p>At first, Podrick had asked his racoon friends for help.</p><p>The raccoons were enthusiastic builders, but they were chaotic. &quot;Hey Podrick!&quot; a raccoon shouted, straining to shove a green hose into a square pipe. &quot;I&#39;ve built the perfect intake system!&quot; &quot;That&#39;s great,&quot; Podrick sighed, &quot;but how do I connect your intake system to the other plots?&quot;</p><p>He turned to the second raccoon, who was cluelessly trying to drill holes into a puddle of water. &quot;I have the most advanced tools,&quot; the raccoon insisted, &quot;but for some reason, I don&#39;t seem to make any progress!&quot;</p><p>Meanwhile, the third raccoon ignored them both, meticulously sorting and stacking smooth pebbles. It was a beautiful way of organizing, but it didn&#39;t help Podrick on the quest for the perfect plot.</p><p>Each built their own way, using their own tools, speaking their own languages. If a plot broke, Podrick had to find the builder and understand their logic. Podrick was tired.</p><p><img src="'+g+'" alt="podrick meets three raccoons that represent providers of kubernetes distributions"></p><h2 id="explanation-providers" tabindex="-1"><em>Explanation: Providers</em> <a class="header-anchor" href="#explanation-providers" aria-label="Permalink to &quot;*Explanation: Providers*&quot;">​</a></h2><ul><li>There are many ways to get and maintain a Kubernetes cluster.</li><li>Different offerings provide different features and configuration options.</li><li>Each provider has their own release/adoption cycle for new Kubernetes version and features.</li></ul><img src="'+a+'" style="width:50%;" alt="raccoon representing a kubernetes provider"><hr><p>One day, seeking a break from the chaos, Podrick tunneled further than ever before. He popped his head out of the soil and gasped.</p><p>Before him lay a magnificent, standardized plot. It was lush, perfectly irrigated, and teeming with activity. But there were no raccoons here. Instead, there were friendly, yellow-and-black striped bees.</p><p>The bees moved with a hive mind, checking the plants, pruning leaves, and watering roots with mathematical precision.</p><p>&quot;Excuse me,&quot; Podrick chirped. &quot;Who built this?&quot;</p><p>A worker bee buzzed down. &quot;We maintain the plot, little worm. But we did not design it. We follow the orders of the hive.&quot;</p><p>&quot;Can I get a plot like this?&quot; Podrick asked. &quot;I have so many plants.&quot;</p><p>&quot;We are but workers,&quot; the bee hummed. &quot;If you desire a plot, you must go to the center of the world. You must visit the Great Library of Plants and speak to the Botanist.&quot;</p><p><img src="'+f+'" alt="podrick meets the bees tending to a farm plot"></p><hr><p>Podrick traveled until he reached the Great Library of Plants (<em>The Garden cluster</em>). It was a place of immense order. The walls were lined with books and thousands of rolled-up parchments.</p><p>At the center sat the Botanist (<em>The Gardener API Server</em>). She was a wise, towering figure who seemed to know the location of every seed in the world.</p><p>&quot;Welcome, Podrick,&quot; she said, her voice like rustling leaves. &quot;The bees told me you seek order.&quot;</p><p>&quot;I need plots,&quot; Podrick said. &quot;But not like the raccoons build. I need them to be the same, no matter where they are.&quot;</p><p><img src="'+b+'" alt="podrick meets the botanist in the great library of plants"></p><h2 id="explanation-garden" tabindex="-1"><em>Explanation: Garden</em> <a class="header-anchor" href="#explanation-garden" aria-label="Permalink to &quot;*Explanation: Garden*&quot;">​</a></h2><ul><li>A dedicated Kubernetes cluster hosting the definition of other Kubernetes clusters.</li><li>The management plane of a Gardener installation.</li><li>Central entry point to manage the lifecycle of a Kubernetes cluster.</li></ul><img src="'+r+`" style="width:50%;" alt="the great library of plants representing the garden cluster"><hr><p>The Botanist nodded and handed him a blank piece of parchment. &quot;In the Great Library of Plants, we do not build with hammers and nails. We build with intent. This is a Scroll of Desire.&quot;</p><p>&quot;I just... write what I want?&quot;</p><p>&quot;Exactly,&quot; the Botanist smiled. &quot;Do not tell us how to build the fence. Just write that you want a fence. Do not tell us how to make the soil wet. Just write that you need humidity. This is the declarative way.&quot;</p><p>Podrick took a quill. He wrote:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Podrick&#39;s Orchid Patch</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Soil Type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Special Orchid Soil</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">3 large acres</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Soil Humidity</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">40% - 70%</span></span></code></pre></div><p>He handed it back. The Botanist read the scroll and asked back: &quot;And where shall we build this patch?&quot;</p><p>&quot;There is a beautiful and well-suited area in the rainy forest.&quot;, Podrick answered and pointed to a spot on a map.</p><p>&quot;Very well&quot;, said the Botanist. She took a seal and stamped it. &quot;It is accepted. Now, meet your guide.&quot;</p><p><img src="`+y+'" alt="podrick writes a scroll of desire that represents the shoot cluster definition"></p><h2 id="explanation-shoot" tabindex="-1"><em>Explanation: Shoot</em> <a class="header-anchor" href="#explanation-shoot" aria-label="Permalink to &quot;*Explanation: Shoot*&quot;">​</a></h2><ul><li>A resource served by the Garden cluster.</li><li>Represents a Kubernetes cluster and the desired state of its configuration.</li><li>Every user brings their own infrastructure accounts and grants Gardener access to manage Kubernetes cluster in there.</li></ul><img src="'+i+'" style="width:50%;" alt="a scroll representing the shoot resource"><hr><p>A mechanical whirring filled the air. Descending from the library&#39;s dome was a gleaming, mechanical hummingbird with lenses for eyes.</p><p>&quot;This is Gilly,&quot; the Botanist introduced her. &quot;Gilly is one of many Gardenlets. She does not live here in the library. She lives in her own nursery (<em>The Seed Cluster</em>), but she watches my library constantly. The moment I stamped that scroll, she saw it.&quot;</p><p>Gilly hovered in front of Podrick. &quot;Target acquired: Podrick&#39;s Orchid Patch. Destination: The nursery. Hop on, little worm.&quot;</p><p>Podrick crawled onto Gilly’s metallic back, and they zipped away, leaving the Great Library of Plants behind.</p><p><img src="'+k+'" alt="a mechanical hummingbird called gilly representing the gardenlet"></p><h2 id="explanation-gardenlet" tabindex="-1"><em>Explanation: Gardenlet</em> <a class="header-anchor" href="#explanation-gardenlet" aria-label="Permalink to &quot;*Explanation: Gardenlet*&quot;">​</a></h2><ul><li>A controller like the Kubelet.</li><li>Turns a given Kubernetes cluster into a Seed cluster.</li><li>Manages all Shoots (Kubernetes clusters) scheduled there.</li></ul><img src="'+n+'" style="width:50%;" alt="a mechanical hummingbird called gilly representing the gardenlet"><hr><p>They arrived at the nursery (<em>The Seed Cluster</em>). It was a massive, protected greenhouse. Inside, Podrick saw something strange. There were hundreds of beehives (<em>Control Planes</em>), all buzzing safely inside the glass walls.</p><p>&quot;Look,&quot; Gilly pointed with her beak. &quot;That is where the maintainers of the plots live.&quot;</p><p>&quot;The maintainers?&quot;</p><p>&quot;The beehives,&quot; Gilly explained. &quot;Each hive is responsible for a different plot. We keep them here, in the nursery, safe and warm. We do not leave the queens out in the cold rain of the actual plots.&quot;</p><p>Gilly flew to an empty spot in the nursery. She began moving quicker than Podrick&#39;s eyes could follow and soon a new beehive labeled Podrick’s Orchid Patch started to grow.</p><p>&quot;The beehive is ready,&quot; Gilly chirped. &quot;But before the bees can settle in, we need the beavers.&quot;</p><p><img src="'+w+'" alt="podrick with gilly in a nursery representing the seed cluster"></p><h2 id="explanation-seed-cluster" tabindex="-1"><em>Explanation: Seed Cluster</em> <a class="header-anchor" href="#explanation-seed-cluster" aria-label="Permalink to &quot;*Explanation: Seed Cluster*&quot;">​</a></h2><ul><li>A Kubernetes cluster hosting Shoot control planes as its workload.</li><li>Is managed by a Gardenlet.</li><li>Each Shoot control plane runs separately in a dedicated namespace.</li><li>Only the Kubernetes API server is exposed to the user.</li></ul><img src="'+o+'" style="width:50%;" alt="a greenhouse which is the nursery representing the seed cluster"><hr><p>Gilly whistled, and a door at the back of the nursery opened. Out waddled a team of sturdy beavers wearing hardhats.</p><p>One of them operated heavy machinery; a wooden excavator. The others brought tools and material for construction.</p><p>&quot;The scroll of desire says you want &#39;Special Orchid Soil&#39;,&quot; Gilly read from her memory banks. &quot;And it should be in the rainy forest.&quot; She showed the beavers the spot on the map. It was the same one Podrick had pointed out to the Botanist back at the library.</p><p>Podrick watched in awe as the beavers marched out of the nursery and into the wild lands. Because the beavers were experts, they didn&#39;t care if the ground was sandy, rocky, or clay. They had different attachments for their wooden excavator for each terrain.</p><p>Podrick watched them work. The beavers cleared the land and built the infrastructure which quickly became a plot.</p><p><img src="'+q+'" alt="podrick and the infrastructure beavers arrived at the plot"></p><h2 id="explanation-infrastructure-extensions" tabindex="-1"><em>Explanation: Infrastructure Extensions</em> <a class="header-anchor" href="#explanation-infrastructure-extensions" aria-label="Permalink to &quot;*Explanation: Infrastructure Extensions*&quot;">​</a></h2><ul><li>Gardener defines interfaces for creating infrastructure such as a Virtual Private Cloud (VPC).</li><li>Extensions implement the interfaces.</li><li>Extensions are deployed to the Seed cluster and create actual resources on the infrastructure provider.</li></ul><img src="'+s+'" style="width:50%;" alt="beaver with a hardhat and sledge hammer representing the infrastructure extension"><hr><p>The beavers finished their tasks in no time.</p><p>Podrick stood on his new plot. It was perfect. The friendly bees (from the hive in the nursery) had flown out to the plot to tend his plants.</p><p>The beavers were close by, ready to repair the plot if it broke.</p><p><img src="'+v+'" alt="podrick, the infrastructure beavers and worker bees at the finished plot"></p><h2 id="explanation-machine-controller-manager" tabindex="-1"><em>Explanation: Machine Controller Manager</em> <a class="header-anchor" href="#explanation-machine-controller-manager" aria-label="Permalink to &quot;*Explanation: Machine Controller Manager*&quot;">​</a></h2><ul><li>Runs on the Seed cluster.</li><li>Has domain specific implementations on board to manage actual machines on a given infrastructure.</li><li>Machines become the Nodes of the cluster.</li></ul><img src="'+l+'" style="width:50%;" alt="beaver with a hardhat and shovel representing the machine controller manager"><hr><p>Together with Gilly Podrick went back to the Great Library of Plants.</p><p>&quot;Gilly,&quot; Podrick asked, &quot;Is this the only nursery? What if I want to plant my ice-ferns in the frozen north?&quot;</p><p>Before Gilly could answer, the soft voice of the Botanist echoed through the Great Library halls. &quot;The garden world is much larger than one greenhouse, little worm.&quot;</p><p>The Botanist led Gilly and Podrick to a balcony overseeing vastly different lands.</p><p>&quot;We have nurseries everywhere,&quot; the Botanist explained, gesturing to the horizon. &quot;From the frozen north to the tropical south and from the coasts to the mountains. In every single one of them, there lives a Gardenlet, just like Gilly.&quot;</p><p>Gilly chirped in agreement. &quot;My siblings. We all watch the library. We all wait for the scrolls.&quot;</p><p>Podrick’s mind raced. &quot;So... if I write a scroll for the frozen north, I don&#39;t need to travel there? I don&#39;t need to find new racoons or learn how to build on ice?&quot;</p><p>&quot;Correct,&quot; the Botanist smiled. &quot;You simply write a scroll of desire specifying &#39;Ice Soil&#39; and the region &#39;North&#39;. The Gardenlet in that distant nursery will see it, send out the local beavers, and build your plot exactly as you requested.&quot;</p><p><img src="'+_+'" alt="podrick and the botanist overlooking the many different nurseries and gillys"></p><h2 id="explanation-scaling" tabindex="-1"><em>Explanation: Scaling</em> <a class="header-anchor" href="#explanation-scaling" aria-label="Permalink to &quot;*Explanation: Scaling*&quot;">​</a></h2><ul><li>Many Seeds can be registered with a single Garden cluster.</li><li>Seeds can be on different infrastructures and regions.</li><li>In heavy-use regions, multiple Seeds can be created.</li></ul><img src="'+x+'" style="width:50%;" alt="multiple mechanical hummingbirds representing multiple gardenlets"><hr><p>Back at the Botanist&#39;s desk in the Great Library halls, Podrick looked at his single scroll. He realized he didn&#39;t just have a plot; he had a system. He could manage a thousand plots, all with different needs, on all imaginable landscapes.</p><p>&quot;I can have all my plants,&quot; Podrick whispered, &quot;In all the perfect places. And I just have to describe what I need to grow them.&quot;</p><p>&quot;That is the power of the system I created,&quot; the Botanist said, resting in her chair. &quot;You define the What. We handle the How. I like to simply call it the way of the Gardener.&quot;</p><p><img src="'+P+'" alt="podrick and gilly back at the botanist&#39;s desk in the great library of plants"></p><hr><p>Just as Podrick felt a wave of relief, a sudden realization struck him, causing him to freeze. &quot;Wait! I forgot something terrible!&quot;</p><p>Gilly tilted her metallic head. &quot;What is it?&quot;</p><p>&quot;My orchids,&quot; Podrick stammered. &quot;They grow. Fast. I only asked for 3 acres of soil. When they get too big, they&#39;ll be crushed!&quot;</p><p>The Botanist let out a sound that resembled a chuckle. &quot;Podrick, do you think the scroll is carved in stone?&quot;</p><p>&quot;It&#39;s... parchment?&quot;</p><p>&quot;It is a living manifesto,&quot; the Botanist explained. &quot;If your plants grow, you do not need to build a new plot. You simply update the scroll. You can change the line &#39;Size: 3 acres&#39; to &#39;Size: Auto-manage up to 10 acres&#39;. When the beavers see the plot getting crowded, they will automatically clear more land and expand the fences. This is autoscaling.&quot;</p><p><img src="'+E+'" alt="podrick and the beavers back at the expanded plot"></p><h2 id="explanation-day-2-operations" tabindex="-1"><em>Explanation: Day-2 Operations</em> <a class="header-anchor" href="#explanation-day-2-operations" aria-label="Permalink to &quot;*Explanation: Day-2 Operations*&quot;">​</a></h2><ul><li>Updates like changing the Node pool size or Kubernetes version is done via the Shoot resource.</li><li>Shoot clusters are reconciled regularly and pick up upstream changes automatically.</li><li>Cluster operations like scaling or replacing a broken node happen automatically.</li><li>ETCD backups protect against infrastructure failures.</li></ul><img src="'+I+'" style="width:50%;" alt="scrolls, the mechanical hummingbird, and the beehive representing day-2 operations"><hr><p>Relieved that his plants are well maintained by Gilly, the beavers and bees, Podrick traveled home.</p><p>As he met his racoon friends, he invited them over to have a cup of tea. The racoons did not have to worry about plots anymore. Instead, they listened to Podrick as he told the story of his journey and the encounter with the Botanist.</p><p>The End.</p><p><img src="'+T+'" alt="podrick and the raccoons in a living room in front of a cozy fireplace"></p><h2 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Illustration</th><th>Term</th><th>Definition</th></tr></thead><tbody><tr><td><img src="'+t+'" style="width:50%;" alt="a farm plot growing different vegetables representing a kubernetes cluster"></td><td>Kubernetes Cluster</td><td>Orchestrator of containerized workloads.</td></tr><tr><td><img src="'+a+'" style="width:50%;" alt="raccoon representing a kubernetes provider"></td><td>Providers</td><td>Offerings or tools to manage a Kubernetes cluster.</td></tr><tr><td><img src="'+r+'" style="width:50%;" alt="the great library of plants representing the garden cluster"></td><td><a href="/docs/gardener/concepts/operator/#garden-resources">Garden</a></td><td>Management plane of the system where a user defines how their Kubernetes clusters should look like.</td></tr><tr><td><img src="'+i+'" style="width:50%;" alt="a scroll representing the shoot resource"></td><td><a href="/docs/gardener/concepts/apiserver/#shoots">Shoot</a></td><td>Resource describing the desired and actual state of a Kubernetes cluster.</td></tr><tr><td><img src="'+o+'" style="width:50%;" alt="a greenhouse which is the nursery representing the seed cluster"></td><td><a href="/docs/gardener/concepts/gardenlet/#seed-controller">Seed</a></td><td>A Kubernetes cluster hosting other Kubernetes cluster&#39;s control planes as workloads.</td></tr><tr><td><img src="'+n+'" style="width:50%;" alt="a mechanical hummingbird called gilly representing the gardenlet"></td><td><a href="/docs/gardener/concepts/gardenlet/">Gardenlet</a></td><td>Just like a Kubelet for Nodes, a Gardenlet turns a Kubernetes cluster into a Seed. The Gardenlet has the core logic to manage Kubernetes clusters.</td></tr><tr><td><img src="'+s+'" style="width:50%;" alt="beaver with a hardhat and sledge hammer representing the infrastructure extension"></td><td><a href="/docs/extensions/">Infrastructure Extensions</a></td><td>With knowledge about the actual infrastructure, they manage resources such as Virtual Private Clouds (VPCs).</td></tr><tr><td><img src="'+l+'" style="width:50%;" alt="beaver with a hardhat and shovel representing the machine controller manager"></td><td><a href="/docs/other-components/machine-controller-manager/">Machine Controller Manager</a></td><td>Responsible for the lifecycle of a Machine, which represents a Kubernetes cluster&#39;s Node.</td></tr></tbody></table>',126)]))}const M=h(G,[["render",B]]);export{z as __pageData,M as default};
